#include "chimera/mobile/package_manager.hpp"
namespace chimera::mobile { bool PackageManager::install(Package p){ if(p.name.empty()||p.entry_activity.empty()||p.abi.empty()) return false; packages_[p.name]=std::move(p); return true; } bool PackageManager::uninstall(const std::string& n){ return packages_.erase(n)!=0; } const Package* PackageManager::find(const std::string& n) const { auto i=packages_.find(n); return i==packages_.end()?nullptr:&i->second; } std::vector<Package> PackageManager::list() const { std::vector<Package> v; for(auto const& [k,p]:packages_) v.push_back(p); return v; } }
